{
  "name": "develoz-race-control",
  "version": "0.1.1",
  "description": "Auto-declares Race Control model profiles (p1, p2, p3, gt3, gt4, tcr, and variants) in opencode without per-project provider config.",
  "type": "module",
  "main": "./dist/race-control.js",
  "types": "./dist/package.d.ts",
  "exports": {
    ".": {
      "types": "./dist/package.d.ts",
      "import": "./dist/race-control.js"
    },
    "./server": {
      "types": "./dist/package.d.ts",
      "import": "./dist/race-control.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc && dts-bundle-generator --project tsconfig.json --external-inlines @opencode-ai/plugin @opencode-ai/sdk zod --no-banner -o dist/package.d.ts -- src/index.ts && bun build src/index.ts --outfile=dist/race-control.js --format=esm --target=node",
    "bundle": "bun build src/index.ts --outfile=dist/race-control.js --format=esm --target=node",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "preqa": "bun run build",
    "qa": "qa ci",
    "qa:lint": "qa lint",
    "qa:fix": "qa lint --fix"
  },
  "overrides": {
    "effect": "4.0.0-beta.103",
    "toml": "5.0.1",
    "zod": "4.6.7"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "race-control",
    "cli-proxy-api"
  ],
  "license": "MIT",
  "devDependencies": {
    "@develoz/quality-assurance": "^0.2.1",
    "@opencode-ai/plugin": "^1.18.5",
    "@types/node": "^24.0.0",
    "dts-bundle-generator": "^10.0.0",
    "jsonata": "^2.2.2",
    "typescript": "^5.8.0"
  }
}
